class Solution {
public:
    int beautifulSplits(vector<int>& nums) {
        int n = nums.size();
        vector<vector<short>> lcp(n + 1, vector<short>(n + 1, 0));
        for (int i = n - 1; i >= 0; i--)
            for (int j = n - 1; j >= 0; j--)
                if (nums[i] == nums[j]) lcp[i][j] = lcp[i + 1][j + 1] + 1;
        int ans = 0;
        for (int i = 1; i < n - 1; i++) {
            bool c1 = lcp[0][i] >= i;
            for (int j = i + 1; j < n; j++)
                if (c1 || lcp[i][j] >= j - i) ans++;
        }
        return ans;
    }
};

