class Solution {
    typedef unsigned long long ull;
    static constexpr ull MOD = (1ULL << 61) - 1;
    ull mulmod(ull a, ull b) { return (__uint128_t)a * b % MOD; }
public:
    int beautifulSplits(vector<int>& nums) {
        int n = nums.size();
        vector<ull> h(n + 1, 0), p(n + 1, 1);
        for (int i = 0; i < n; i++) {
            h[i + 1] = (mulmod(h[i], 131) + nums[i]) % MOD;
            p[i + 1] = mulmod(p[i], 131);
        }
        auto hh = [&](int l, int k) {
            return (h[l + k] + MOD - mulmod(h[l], p[k])) % MOD;
        };
        auto lcpq = [&](int a, int b) {
            int lo = 0, hi = min(n - a, n - b);
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (hh(a, mid) == hh(b, mid)) lo = mid; else hi = mid - 1;
            }
            return lo;
        };
        int ans = 0;
        for (int i = 1; i < n - 1; i++) {
            bool c1 = lcpq(0, i) >= i;
            for (int j = i + 1; j < n; j++)
                if (c1 || lcpq(i, j) >= j - i) ans++;
        }
        return ans;
    }
};

