class Solution {
    static final long MOD = (1L << 61) - 1;
    private long mulmod(long a, long b) {
        return java.math.BigInteger.valueOf(a).multiply(java.math.BigInteger.valueOf(b)).mod(java.math.BigInteger.valueOf(MOD)).longValue();
    }
    public int beautifulSplits(int[] nums) {
        int n = nums.length;
        long[] h = new long[n + 1], p = new long[n + 1];
        p[0] = 1;
        for (int i = 0; i < n; i++) {
            h[i + 1] = (mulmod(h[i], 131) + nums[i]) % MOD;
            p[i + 1] = mulmod(p[i], 131);
        }
        int ans = 0;
        for (int i = 1; i < n - 1; i++) {
            boolean c1 = lcp(h, p, n, 0, i) >= i;
            for (int j = i + 1; j < n; j++)
                if (c1 || lcp(h, p, n, i, j) >= j - i) ans++;
        }
        return ans;
    }
    private int lcp(long[] h, long[] p, int n, int a, int b) {
        int lo = 0, hi = Math.min(n - a, n - b);
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            long x = ((h[a + mid] - mulmod(h[a], p[mid])) % MOD + MOD) % MOD;
            long y = ((h[b + mid] - mulmod(h[b], p[mid])) % MOD + MOD) % MOD;
            if (x == y) lo = mid; else hi = mid - 1;
        }
        return lo;
    }
}

